// Dictionary data (generated by scripts/build-data.mjs) plus everything derived from it once at start-up.
import { max } from "d3";
import RAW from "./data/dictionary.json";

export const { nodes, links } = RAW;
export const SECTIONS = RAW.sections || [];
export const PATHS = RAW.paths || [];
export const byId = new Map(nodes.map(n => [n.id, n]));

nodes.forEach(n => { n.out = new Set(); n.in = new Set(); });
links.forEach(l => { byId.get(l.source).out.add(l.target); byId.get(l.target).in.add(l.source); });
nodes.forEach(n => { n.deg = n.out.size + n.in.size; n.near = new Set([...n.out, ...n.in]); });
export const maxDeg = max(nodes, n => n.deg) || 1;
/** The term plus its direct neighbours, for framing the camera. */
export const withNeighbours = n => [n, ...[...n.near].map(id => byId.get(id))];

export const LEVELS = { beginner: { n: 1, label: "Beginner" }, intermediate: { n: 2, label: "Intermediate" }, advanced: { n: 3, label: "Advanced" } };
export const lvBars = lv => "●".repeat(LEVELS[lv].n) + "○".repeat(3 - LEVELS[lv].n);
export const levelCounts = {};
nodes.forEach(n => { levelCounts[n.level] = (levelCounts[n.level] || 0) + 1; });
export const secVar = i => `var(--sec${(i >= 0 ? i : 6) + 1})`;
export const sectionName = i => (SECTIONS[i] || {}).name || "";

/* graph sizes */
export const radius = n => 4 + Math.sqrt(n.deg) * 2.6;

/* timeline: date as a fractional year, lineage both ways, chronological rank */
const tv = h => { const [y, mo] = h.date.split("-"); return +y + (mo ? (+mo - 0.5) / 12 : 0.5); };
export const tlNodes = nodes.filter(n => n.history);
tlNodes.forEach(n => { n.t = tv(n.history); n.kids = new Set(); n.history.from = n.history.from.filter(f => byId.has(f)); });
tlNodes.forEach(n => n.history.from.forEach(f => { const p = byId.get(f); if (p.history) p.kids.add(n.id); }));
tlNodes.slice().sort((a, b) => a.t - b.t).forEach((n, i) => { n.rank = i; });
export const tlEdges = tlNodes.flatMap(n => n.history.from.map(f => byId.get(f)).filter(p => p.history).map(p => ({ s: p, t: n })));
export const byTime = (a, b) => a.t - b.t || a.rank - b.rank;

export const LANES = SECTIONS.length ? SECTIONS.map(s => s.name) : ["All terms"];
tlNodes.forEach(n => { n.lane = n.section >= 0 ? n.section : LANES.length - 1; });
export const rr = n => 3.5 + Math.sqrt(n.deg) * 1.45;
